#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    long long rounds = 0;
    int size = n;
    while (size > 1) {
        rounds = rounds + n;
        size = size / 2;
    }

    printf("层层砍半：%lld {unit}\n", rounds);
    return 0;
}
